"use client";

import { cjk } from "@streamdown/cjk";
import { code } from "@streamdown/code";
import { math } from "@streamdown/math";
import { mermaid } from "@streamdown/mermaid";
import { Streamdown } from "streamdown";

interface ReadmeContentProps {
  children: string;
}

const stripImages = (markdown: string): string =>
  markdown
    // Remove markdown images: ![alt](url)
    .replace(/!\[[^\]]*\]\([^)]*\)/g, "")
    // Remove HTML img tags: <img ... /> or <img ...>
    .replace(/<img[^>]*\/?>/gi, "")
    // Clean up empty lines left behind
    .replace(/^\s*\[?\s*\]?\s*$/gm, "");

export const ReadmeContent = ({ children }: ReadmeContentProps) => (
  <Streamdown
    linkSafety={{ enabled: false }}
    mode="static"
    plugins={{ cjk, code, math, mermaid }}
  >
    {stripImages(children)}
  </Streamdown>
);

import { readFileSync } from "node:fs";
import { basename } from "node:path";
import { describe, expect, it } from "vitest";
import {
  extractTypeScriptBlocks,
  findPackageReadmes,
  IMPORT_PACKAGE_REGEX,
  VALID_PACKAGE_README_IMPORTS,
} from "./documentation-test-utils";

describe("Package README code examples", () => {
  const packageReadmes = findPackageReadmes();

  for (const { path: readmePath, name: readmeName } of packageReadmes) {
    const pkgName = basename(readmePath.replace("/README.md", ""));

    it(`${pkgName} README should have TypeScript examples with valid syntax`, () => {
      const readme = readFileSync(readmePath, "utf-8");
      const codeBlocks = extractTypeScriptBlocks(readme);

      if (codeBlocks.length === 0) {
        return;
      }

      for (const block of codeBlocks) {
        const openBraces = (block.match(/{/g) || []).length;
        const closeBraces = (block.match(/}/g) || []).length;
        const openParens = (block.match(/\(/g) || []).length;
        const closeParens = (block.match(/\)/g) || []).length;

        expect(
          openBraces,
          `${readmeName}: Mismatched braces in code block`
        ).toBe(closeBraces);
        expect(
          openParens,
          `${readmeName}: Mismatched parentheses in code block`
        ).toBe(closeParens);

        const importMatches = block.match(/from ["']([^"']+)["']/g) || [];
        for (const importMatch of importMatches) {
          const pkg = importMatch.match(IMPORT_PACKAGE_REGEX)?.[1];
          if (pkg && !pkg.startsWith(".") && !pkg.startsWith("@/")) {
            const isValid =
              VALID_PACKAGE_README_IMPORTS.includes(pkg) ||
              pkg.startsWith("node:");
            expect(
              isValid,
              `${readmeName}: Unknown import "${pkg}" in code block`
            ).toBe(true);
          }
        }
      }
    });
  }
});

import { execSync } from "node:child_process";
import { readFileSync, rmSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import {
  createTempProject,
  extractTypeScriptBlocks,
  REPO_ROOT,
} from "./documentation-test-utils";

describe("Main README.md code examples", () => {
  const mainReadmePath = join(REPO_ROOT, "README.md");

  it("should contain valid TypeScript that type-checks", () => {
    const readme = readFileSync(mainReadmePath, "utf-8");
    const codeBlocks = extractTypeScriptBlocks(readme);
    expect(codeBlocks.length).toBeGreaterThan(0);

    const tempDir = createTempProject(codeBlocks);

    try {
      execSync(`pnpm exec tsc --project ${tempDir}/tsconfig.json --noEmit`, {
        cwd: REPO_ROOT,
        encoding: "utf-8",
        stdio: "pipe",
      });
    } catch (error) {
      const execError = error as { stdout?: string; stderr?: string };
      const output = execError.stdout || execError.stderr || String(error);

      expect.fail(
        `README.md TypeScript code blocks failed type-checking:\n\n${output}\n\n` +
          `Code blocks tested:\n${codeBlocks
            .map((block, index) => `--- Block ${index} ---\n${block}`)
            .join("\n\n")}`
      );
    } finally {
      rmSync(tempDir, { recursive: true, force: true });
    }
  });

  it("should have a bot definition example", () => {
    const readme = readFileSync(mainReadmePath, "utf-8");
    const codeBlocks = extractTypeScriptBlocks(readme);

    const hasBotDefinition = codeBlocks.some(
      (block) => block.includes("new Chat") && block.includes("adapters:")
    );

    expect(
      hasBotDefinition,
      "README should have a Chat instantiation example"
    ).toBe(true);
  });
});

"use client";

import { track } from "@vercel/analytics";
import { CheckIcon, CopyIcon } from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
  InputGroupText,
} from "@/components/ui/input-group";

const COPY_TIMEOUT = 2000;

interface InstallerProps {
  className?: string;
  command: string;
}

export const Installer = ({ command, className = "w-48" }: InstallerProps) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(command);
    toast.success("Copied to clipboard");
    setCopied(true);

    track("Copied installer command");
    setTimeout(() => {
      setCopied(false);
    }, COPY_TIMEOUT);
  };

  const Icon = copied ? CheckIcon : CopyIcon;

  return (
    <InputGroup className="h-10 bg-background font-mono shadow-none">
      <InputGroupAddon>
        <InputGroupText className="font-normal text-muted-foreground">
          $
        </InputGroupText>
      </InputGroupAddon>
      <InputGroupInput className={className} readOnly value={command} />
      <InputGroupAddon align="inline-end">
        <InputGroupButton
          aria-label="Copy"
          onClick={handleCopy}
          size="icon-xs"
          title="Copy"
        >
          <Icon className="size-3.5" size={14} />
        </InputGroupButton>
      </InputGroupAddon>
    </InputGroup>
  );
};

const BOT_SCOPES = [
  "app_mentions:read",
  "channels:history",
  "channels:read",
  "chat:write",
  "files:read",
  "groups:history",
  "groups:read",
  "im:history",
  "im:read",
  "im:write",
  "mpim:history",
  "mpim:read",
  "reactions:read",
  "reactions:write",
  "users:read",
];

export function GET() {
  const clientId = process.env.SLACK_CLIENT_ID;

  if (!clientId) {
    return new Response("SLACK_CLIENT_ID is not configured", { status: 500 });
  }

  const installUrl = new URL("https://slack.com/oauth/v2/authorize");
  installUrl.searchParams.set("client_id", clientId);
  installUrl.searchParams.set("scope", BOT_SCOPES.join(","));

  return Response.redirect(installUrl.toString(), 302);
}

const LINEAR_INSTALL_SCOPES = [
  "read",
  "write",
  "comments:create",
  "issues:create",
  "app:mentionable",
];

export function GET() {
  const clientId = process.env.LINEAR_CLIENT_ID;
  const redirectUri = process.env.LINEAR_REDIRECT_URI;

  if (!clientId) {
    return new Response("LINEAR_CLIENT_ID is not configured", { status: 500 });
  }

  if (!redirectUri) {
    return new Response("LINEAR_REDIRECT_URI is not configured", {
      status: 500,
    });
  }

  const installUrl = new URL("https://linear.app/oauth/authorize");
  installUrl.searchParams.set("client_id", clientId);
  installUrl.searchParams.set("redirect_uri", redirectUri);
  installUrl.searchParams.set("response_type", "code");
  installUrl.searchParams.set("actor", "app");
  installUrl.searchParams.set("scope", LINEAR_INSTALL_SCOPES.join(","));

  return Response.redirect(installUrl.toString(), 302);
}

