"use server";

import { headers } from "next/headers";
import type { Feedback } from "@/components/geistdocs/feedback";
import { siteId } from "@/geistdocs";
import { emotions } from "./emotions";

const protocol = process.env.NODE_ENV === "production" ? "https" : "http";
const baseUrl = `${protocol}://${process.env.NEXT_PUBLIC_VERCEL_PROJECT_PRODUCTION_URL}`;

export const sendFeedback = async (
  url: string,
  feedback: Feedback
): Promise<{ success: boolean }> => {
  const emoji = emotions.find((e) => e.name === feedback.emotion)?.emoji;
  const endpoint = new URL("/feedback", "https://geistdocs.com/feedback");
  const headersList = await headers();

  const response = await fetch(endpoint, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      note: feedback.message,
      url: new URL(url, baseUrl).toString(),
      emotion: emoji,
      ua: headersList.get("user-agent") ?? undefined,
      ip: headersList.get("x-real-ip") || headersList.get("x-forwarded-for"),
      label: siteId,
    }),
  });

  if (!response.ok) {
    const error = await response.json();

    console.error(error);

    return { success: false };
  }

  return {
    success: true,
  };
};

import { bot } from "@/lib/bot";

export async function GET(request: Request) {
  const adapter = bot.getAdapter("slack");

  if (!adapter) {
    return new Response("Slack adapter not configured", { status: 500 });
  }

  try {
    await bot.initialize();
    const { teamId } = await adapter.handleOAuthCallback(request);
    return new Response(`Slack app installed for team ${teamId}!`);
  } catch (error) {
    console.error("[slack/install/callback] OAuth error:", error);
    return new Response("OAuth installation failed", { status: 500 });
  }
}

import { bot } from "@/lib/bot";

export async function GET(request: Request) {
  const adapter = bot.getAdapter("linear");
  const redirectUri = process.env.LINEAR_REDIRECT_URI;

  if (!adapter) {
    return new Response("Linear adapter not configured", { status: 500 });
  }

  if (!redirectUri) {
    return new Response("LINEAR_REDIRECT_URI is not configured", {
      status: 500,
    });
  }

  try {
    await bot.initialize();
    const { organizationId } = await adapter.handleOAuthCallback(request, {
      redirectUri,
    });
    return new Response(
      `Linear app installed for organization ${organizationId}!`
    );
  } catch (error) {
    console.error("[linear/install/callback] OAuth error:", error);
    return new Response("OAuth installation failed", { status: 500 });
  }
}

